INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65762042', 65762042, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'Balai POM Payakumbuh', 'Belanja Jasa Lainnya', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Barat, Payakumbuh (Kota)', 526289000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan tenaga alih daya (outsourcing) selama 1 (satu) tahun untuk mendukung kelancaran operasional dan pelayanan di lingkungan instansi, dengan rincian sebagai berikut: Tenaga Security Melaksanakan pengamanan lingkungan kantor, pengaturan akses keluar masuk, patroli area, menjaga ketertiban dan keamanan aset, serta melaksanakan tugas pengamanan sesuai standar operasional prosedur. Tenaga Resepsionis Memberikan pelayanan penerimaan tamu, pengelolaan informasi dan komunikasi awal, pengaturan jadwal tamu, serta mendukung pelayanan administrasi front office. Tenaga Supir Mengemudikan dan merawat kendaraan operasional dinas, mendukung kelancaran perjalanan dinas pimpinan/pegawai, serta memastikan kendaraan dalam kondisi laik jalan dan aman. Tenaga Cleaning Service Melaksanakan kebersihan dan kerapihan area kantor, termasuk ruang kerja, ruang pelayanan, toilet, dan lingkungan sekitar kantor sesuai standar kebersihan yang ditetapkan.', 'Pengadaan tenaga alih daya (outsourcing) selama 1 (satu) tahun untuk mendukung operasional kantor, terdiri dari tenaga security, resepsionis, supir, dan cleaning service, dengan ketentuan sebagai berikut: Security: Pendidikan minimal SMA/sederajat, memiliki sertifikat satpam, sehat jasmani rohani, berpengalaman, melaksanakan pengamanan lingkungan kantor sesuai SOP. Resepsionis: Pendidikan minimal SMA/sederajat, komunikatif, berpenampilan rapi, mampu mengoperasikan komputer dasar, melaksanakan pelayanan penerimaan tamu dan front office. Supir: Pendidikan minimal SMA/sederajat, memiliki SIM A aktif, berpengalaman, mengemudikan dan merawat kendaraan operasional dinas. Cleaning Service: Pendidikan minimal SMP/sederajat, sehat jasmani rohani, disiplin, melaksanakan kebersihan dan kerapihan seluruh area kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2332138);
