INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65763954', 65763954, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Kebijakan, Regulasi, dan Pedoman/Pedoman Pelaksanaan Manajemen Risiko Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 295800000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Penyusunan Kajian Kebijakan, Regulasi, dan Pedoman/Pedoman Pelaksanaan Manajemen Risiko Pembangunan Nasional (MRPN) adalah melakukan analisis dan telaah hukum terhadap peraturan perundang-undangan yang terkait dengan kebijakan manajemen risiko pembangunan nasional, penyusunan kajian dan rekomendasi kebijakan serta opsi penguatan regulasi, membuat analisis sinkronisasi regulasi lintas sektor, pendampingan konseptual dan strategis dalam proses perumusan kebijakan, penyediaan referensi best practices dan benchmarking, serta pelaksanaan kegiatan knowledge sharing sebagai bahan pertimbangan pengambilan keputusan', 'Hasil kerja Jasa Konsultan Penyusunan Kajian Kebijakan, Regulasi, dan Pedoman/Pedoman Pelaksanaan Manajemen Risiko Pembangunan Nasional (MRPN) ini adalah Laporan Penyusunan Kajian Kebijakan, Regulasi, dan Pedoman/Pedoman Pelaksanaan Manajemen Risiko Pembangunan Nasional (MRPN) dengan waktu penyelesaian selama 10 (sepuluh) bulan. Jasa Konsultan Penyusunan Kajian Kebijakan, Regulasi, dan Pedoman/Pedoman Pelaksanaan Manajemen Risiko Pembangunan Nasional (MRPN) dalam mendukung Pekerjaan Direktorat Sistem dan Manajemen Risiko memiliki keluaran setiap terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan kajian dan analisis keselarasan perencanaan berbasis risiko dengan regulasi perencanaan pembangunan nasional. 2 Termin 2 Laporan Rancangan Regulasi Juklak Perencanaan Berbasis Risiko (Risk Based Planning) 3 Termin 3 Laporan Rancangan Regulasi Integrasi MRPN pada Proses Pengendalian dan Evaluasi, serta Pelaporan Kinerja Instansi Pemerintah 4 Termin 4 Laporan Rancangan Regulasi Pedoman Pengukuran Efektivitas MRPN. 5 Termin 5 Laporan Rancangan Regulasi Penguatan Model Jejaring Aktor Lintas Sektor (K/L/P/BU/BL). 6 Termin 6 Laporan Penyusunan Kajian Kebijakan, Regulasi, dan Pedoman/Pedoman Pelaksanaan Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2333707);
