INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65763927', 65763927, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Implementasi Tahap Perencanaan dan Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 359352000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup kegiatan Jasa Konsultan Penyusunan Kajian Implementasi Tahap Perencanaan dan Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN) meliputi dukungan bagi Direktorat Sistem dan Manajemen Risiko melalui penyusunan basis data dan analisis teknis untuk optimalisasi MRPN Lintas Sektor di setiap tahapan pembangunan. Konsultan bertanggung jawab mengelola data profil risiko yang akurat guna mendukung kebijakan berbasis risiko, melakukan telaah efektivitas perlakuan risiko untuk merumuskan rekomendasi perbaikan, serta mengoptimalkan fungsionalitas sistem informasi MRPN sebagai instrumen pemantauan digital yang terintegrasi dan real-time. Selain itu, peran ini mencakup sinkronisasi teknis antara kebijakan manajemen risiko dengan sistem pelaporan digital guna meningkatkan kualitas pengendalian pada program strategis nasional.', 'Hasil kerja Jasa Konsultan Penyusunan Kajian Implementasi Tahap Perencanaan dan Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN) ini adalah Laporan Penyusunan Kajian Implementasi Tahap Perencanaan dan Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN) dengan waktu penyelesaian selama 10 (sepuluh) bulan. Jasa Konsultan Penyusunan Kajian Implementasi Tahap Perencanaan dan Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN) dalam mendukung Pekerjaan Direktorat Sistem dan Manajemen Risiko memiliki keluaran setiap terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan Profil Risiko Objek MRPN LS (Tahap Awal). 2 Termin 2 Laporan Rencana Kerja dan Strategi Analisis Data Risiko. 3 Termin 3 Laporan Analisis Profil Risiko untuk Rekomendasi Kebijakan. 4 Termin 4 Laporan Telaah Efektivitas Perlakuan Risiko (Final). 5 Termin 5 Laporan Optimalisasi Fungsionalitas Sistem Informasi. 6 Termin 6 Laporan Penyusunan Kajian Implementasi Tahap Perencanaan dan Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2334040);
