INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65763937', 65763937, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Pelaksanaan Penetapan Objek Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor dan Profil Risiko', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 222525000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Penyusunan Kajian Pelaksanaan Penetapan Objek Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor dan Profil Risiko adalah mendukung penyusunan dan pemutakhiran daftar Objek MRPN LS dan UPR LS melalui tahapan longlist, shortlist, hingga penetapan konsep, disertai sinkronisasi antar pemangku kepentingan. Selain itu, mendukung penyusunan dan pemutakhiran pedoman (juklak/juknis) perencanaan berbasis risiko, termasuk identifikasi, analisis, penyusunan, serta reviu profil risiko Objek MRPN LS. Seluruh proses diintegrasikan dan disinkronkan dengan implementasi perencanaan berbasis risiko pada Direktorat Sistem dan Manajemen Risiko.', 'Hasil kerja Jasa Konsultan Penyusunan Kajian Pelaksanaan Penetapan Objek Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor dan Profil Risiko ini adalah Laporan Penyusunan Kajian Pelaksanaan Penetapan Objek Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor dan Profil Risiko dengan waktu penyelesaian selama 10 (sepuluh) bulan. Jasa Konsultan Penyusunan Kajian Pelaksanaan Penetapan Objek Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor dan Profil Risiko dalam mendukung Pekerjaan Direktorat Sistem dan Manajemen Risiko memiliki keluaran setiap bulannya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan Perencanaan dan Penyusunan Daftar Awal Calon Objek MRPN LS. 2 Termin 2 Laporan Perancangan Objek MRPN LS dan UPR LS. 3 Termin 3 Laporan Pengembangan Pedoman/Juklak MRPN dan Analisis Awal Risiko 4 Termin 4 Laporan Penyusunan dan Reviu Profil Risiko 5 Termin 5 Laporan Penyempurnaan Pedoman/Juklak MRPN 6 Termin 6 Laporan Penyusunan Kajian Pelaksanaan Penetapan Objek Manajemen Risiko Pembangunan Nasional (MRPN) Lintas Sektor dan Profil Risiko', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2334415);
