INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65763948', 65763948, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Asisten Konsultan Pengendalian Perencanaan Dan Pelaksanaan Pembangunan Berbasis Risiko Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 96000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 PAKET', 'KELUARAN Keluaran yang diharapkan dari kegiatan ini adalah: 1. Dokumen Teknis Executive Summary dan Pengendalian Perencanaan KP Percepatan Pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena Dokumen yang memuat draft teknis komponen Executive Summary serta hasil pengendalian perencanaan, termasuk analisis keselarasan target, indikator, dan kebutuhan intervensi KP percepatan pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena dalam siklus perencanaan pembangunan; dan 2. Dokumen Analisis Pengendalian Pelaksanaan dan Evaluasi KP Percepatan Pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena Dokumen yang memuat hasil analisis pengendalian pelaksanaan dan rangkuman evaluasi triwulanan (TW I–TW III), termasuk identifikasi indikasi risiko, hambatan implementasi, serta opsi mitigasi risiko lingkup KP Percepatan Pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena.', 'LINGKUP KEGIATAN Lingkup kegiatan dan tanggung jawab Asisten Konsultan Pengendalian Perencanaan Dan Pelaksanaan Pembangunan Berbasis Risiko Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena adalah sebagai berikut: A. Penguatan Ex-Ante (Pengendalian Perencanaan) 1. Mendesain struktur dan template exsum pengembangan ruang lingkup PN 3 lingkup percepatan pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena; 2. Menyusun panduan teknis pengisian eksum dan data validation ruang lingkup PN 3 lingkup percepatan pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena; 3. Melakukan QA/peer review atas draf exsum, memberi rekomendasi perbaikan ruang lingkup PN 3 lingkup percepatan pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena; 4. Penyusunan model statistik proyeksi indikator; validasi data baseline dan target dan penyusunan sistem monitoring‐indikator berbasis data. Batasan: Konsultan tidak menyusun Exsum atas nama unit kerja, menandatangani/menetapkan dokumen. B. Penguatan On Going (Pengendalian Pelaksanaan) 1. Mendesain mekanisme forum pengendalian triwulanan ruang lingkup PN 3 lingkup percepatan pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena 2. Menyusun catatan teknis pendampingan & rekomendasi ruang lingkup PN 3 lingkup percepatan pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena; 3. Melakukan analisis risiko dinamis ruang lingkup PN 3 lingkup percepatan pembangunan Destinasi Pariwisata Prioritas Lombok-Gili Tramena; 4. Pengembangan mekanisme pengendalian & laporan triwulan berbasis data; Batasan: Konsultan tidak menyusun Laporan Pengendalian Triwulanan resmi, dokumen formal ditetapkan oleh ASN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2334741);
